"""Standalone exercises for the introductory, HTML and CSS presentation topics."""
from course_model import *

def concept(c,id,title,idea,example,question,prompt,answer):
 lesson(c,id,title,idea,example,idea,question,text(prompt,answer,contextCode=example,contextLabel='Situația de analizat'))
def H(c,id,title,idea,code,tests,question,prompt):
 lesson(c,id,title,idea,code,idea,question,html(prompt,code,tests))
def C(c,id,title,idea,code,fixture,tests,question,prompt):
 lesson(c,id,title,idea,code,idea,question,css(prompt,code,fixture,tests))

c=chapter('web-foundations','Web · de la adresă la pagină','Cereri, browsere, căutare, SEO și publicare.','Introducere & HTML.pptx, 3–22','globe')
concept(c,'web-network','Internet și World Wide Web','Internetul transportă date între rețele. Web-ul este un serviciu bazat pe resurse legate prin URL-uri și schimburi HTTP; nu orice serviciu de internet este o pagină web.','Browser → request HTTP → server → response HTTP',q('Ce reprezintă Web-ul?','Un serviciu care folosește internetul','Toate conexiunile de internet','Un singur browser'),'O pagină HTML este cerută prin HTTP. Scrie numele serviciului descris: Web sau email.','Web')
concept(c,'web-frontend','Ce execută browserul','HTML, CSS și JavaScript formează interfața din browser. Browserul nu execută direct un template EJS sau o interogare PostgreSQL.','index.html\nstyle.css\napp.js',q('Unde este aplicat CSS-ul paginii?','În browser','În PostgreSQL','În registrul DNS'),'Cine aplică regulile CSS dintr-o pagină: browser sau database?','browser')
concept(c,'web-backend','Ce execută serverul','Serverul primește cereri, citește date și construiește răspunsuri. Codul backend poate fi JavaScript prin Node; nu este trimis automat ca sursă executabilă către browser.','Browser requests /products\nServer queries products\nServer returns HTML',q('Cine citește baza de date în această arhitectură?','Serverul','Fișierul CSS','Tagul img'),'În arhitectura descrisă, scrie componenta care interoghează baza: server sau browser.','server')
concept(c,'web-fullstack','Leagă interfața de server','Full stack înseamnă lucrul cu partea din browser și partea de server. Schimbul dintre ele trebuie să aibă un format clar, de exemplu HTML sau JSON.','GET /api/products\nContent-Type: application/json',q('Ce format indică application/json?','JSON','CSS','SCSS'),'Scrie formatul de date indicat de antetul Content-Type de mai sus, cu majuscule.','JSON')
concept(c,'web-static-dynamic','Pagini statice și dinamice','O pagină statică poate fi servită ca fișier. O pagină dinamică este construită sau actualizată folosind date. JavaScript poate actualiza și un site găzduit static, dar nu transformă găzduirea în server Node.','Static: HTML file\nDynamic: template + product data → HTML',q('Ce intră în randarea unui template de produse?','Template-ul și datele produselor','Numai un favicon','Doar un fișier video'),'O pagină construită din template și date la fiecare cerere este static sau dynamic? Scrie termenul în engleză.','dynamic')
concept(c,'web-browser-engine','Browser și motor de randare','Motorul de randare interpretează HTML/CSS și calculează layout-ul. Browsere diferite pot avea diferențe de suport; verifică afișarea și funcțiile folosite.','HTML + CSS → layout → pixels',q('Ce calculează layout-ul?','Motorul de randare','Registrul DNS','Parserul SQL'),'Scrie numele rezultatului intermediar care descrie pozițiile și dimensiunile elementelor: layout.','layout')
concept(c,'web-crawler','Cum sunt descoperite paginile','Un crawler urmărește legături și descoperă resurse pentru un motor de căutare. Un text vizibil în browser nu garantează indexarea sau poziția în rezultate.','<a href="/products">Our products</a>',q('Ce ajută crawlerul să descopere o pagină?','Un link către ea','Culoarea monitorului','Numele variabilei locale'),'Ce atribut al legăturii arată destinația către crawler?','href')
concept(c,'web-proxy','Rolul unui proxy','Un proxy intermediază cereri. Poate oferi cache sau rutare, dar nu este sinonim cu aplicația care produce datele.','Client → proxy → origin server',q('Unde este proxy-ul în acest traseu?','Între client și serverul de origine','În interiorul fiecărui tag HTML','Într-o coloană SQL'),'Scrie componenta care intermediază cererea în traseul de mai sus.','proxy')
concept(c,'web-private-pages','Pagină neindexată și pagină protejată','O resursă absentă din rezultatele unui motor de căutare poate fi totuși accesibilă prin URL. Accesul restricționat trebuie verificat de aplicație, nu bazat pe faptul că adresa este greu de ghicit.','/account → server checks access',q('Lipsa din Google garantează protecția accesului?','Nu','Da','Numai dacă URL-ul este lung'),'Cine trebuie să verifice dreptul de acces la /account: server sau crawler?','server')
concept(c,'web-data-minimum','Datele unui formular','Un formular trebuie să ceară date potrivite scopului său. Pentru un mesaj simplu nu este nevoie să soliciți date fără legătură cu răspunsul. Acesta este un principiu de proiectare, nu un aviz juridic.','Contact form: email, message',q('Ce alegere păstrează formularul potrivit scopului?','Câmpurile necesare mesajului','Cât mai multe date personale','Orice câmp găsit într-un alt site'),'Pentru a trimite un răspuns prin email, ce câmp este necesar: email sau shoeSize?','email')
concept(c,'web-image-rights','Imagini și dreptul de utilizare','O imagine găsită online nu este automat liberă pentru reutilizare. Folosește imagini proprii sau resurse cu o licență potrivită și păstrează atribuirea cerută.','Image author: Example Artist\nLicense: attribution required',q('Ce trebuie păstrat când licența cere atribuire?','Creditul autorului','Doar numele fișierului','Parola contului'),'Licența din exemplu cere indicarea autorului. Scrie termenul în engleză pentru această cerință: attribution.','attribution')
H(c,'web-seo-title','Titlu și descriere utile','Un titlu descrie pagina, iar meta description o rezumă. Ele nu înlocuiesc conținutul relevant sau linkurile funcționale.','<!doctype html><html lang="en"><head><title>Handmade cakes | Sweet Corner</title><meta name="description" content="Explore handmade cakes and pastries."></head><body><h1>Handmade cakes</h1></body></html>',[exact('title','Handmade cakes | Sweet Corner'),attr('meta[name="description"]','content','Explore handmade cakes and pastries.'),exact('h1','Handmade cakes')],q('Ce descrie cel mai bine titlul paginii?','Subiectul concret al paginii','O listă de cuvinte repetate','Doar cuvântul Home'),'Creează o pagină cu titlul `Handmade cakes | Sweet Corner`, descrierea `Explore handmade cakes and pastries.` și un h1 `Handmade cakes`.')

c=chapter('html-semantics-complete','HTML · semantica fiecărui element','Text, metadate, legături și alternative moderne pentru tagurile vechi.','Introducere & HTML.pptx, 23–67, 95–104','html')
for tag,title,idea,value in [
 ('b','b · atrage atenția','b atrage atenția fără să declare aceeași importanță semantică precum strong.','New'),
 ('strong','strong · importanță','strong marchează importanță; nu este doar o comandă pentru caractere îngroșate.','Allergen warning'),
 ('i','i · voce diferită','i poate marca un termen într-o altă limbă sau o voce diferită de restul textului.','croissant'),
 ('em','em · accent de sens','em marchează accentul care poate schimba sensul unei propoziții.','today'),
 ('u','u · adnotare','u poate indica o adnotare netextuală; nu îl folosi pentru a simula un link.','misspelled'),
 ('mark','mark · relevanță','mark evidențiază o potrivire sau un fragment relevant în context.','cake'),
 ('small','small · notă secundară','small marchează note secundare, precum condiții sau observații scurte.','Prices include VAT.'),
 ('q','q · citat scurt','q marchează un citat scurt în interiorul unei propoziții.','Fresh every day'),
 ('code','code · fragment de cod','code indică un fragment de cod, fără să păstreze singur toate spațiile și liniile.','const price = 12;'),
 ('kbd','kbd · intrare de la tastatură','kbd reprezintă o tastă sau o secvență introdusă de utilizator.','Ctrl + S'),
 ('samp','samp · ieșirea unui program','samp marchează un exemplu de rezultat produs de program.','Saved successfully'),
 ('var','var · variabilă în text','var indică o variabilă într-o explicație tehnică sau formulă.','total'),
 ('sub','sub · indice inferior','sub este potrivit pentru un indice în text obișnuit, precum cifra din H₂O.','2'),
 ('sup','sup · exponent','sup este potrivit pentru un exponent simplu în text. Pentru formule complexe folosește MathML.','2'),
 ('s','s · informație depășită','s marchează o informație care nu mai este actuală, de exemplu un preț vechi.','20 EUR'),
 ('del','del · eliminare din document','del reprezintă conținut eliminat într-o revizie a documentului.','Old offer'),
 ('ins','ins · adăugare în document','ins reprezintă conținut introdus într-o revizie.','New offer'),
 ('abbr','abbr · abreviere','abbr marchează o abreviere; title poate oferi forma completă.','HTML'),
 ('address','address · informații de contact','address conține informații de contact pentru autorul sau organizația relevantă, nu orice adresă poștală folosită decorativ.','hello@example.com'),
 ('blockquote','blockquote · citat separat','blockquote marchează un citat extins. Atributul cite poate indica sursa, fără a afișa automat un link.','Excellent cakes.')]:
 code=f'<{tag}'+(' title="HyperText Markup Language"' if tag=='abbr' else '')+f'>{value}</{tag}>'
 tests=[exact(tag,value)]
 if tag=='abbr':tests.append(attr(tag,'title','HyperText Markup Language'))
 H(c,'semantic-'+tag,title,idea,code,tests,q('Ce element folosești pentru rolul descris?',tag,'div pentru orice sens','script'),f'Marchează textul `{value}` cu elementul `{tag}`.'+(' Adaugă title cu valoarea `HyperText Markup Language`.' if tag=='abbr' else ''))
H(c,'html-base-url','O bază pentru căile relative','base href schimbă baza folosită la rezolvarea adreselor relative. Folosește-l doar când înțelegi efectul asupra tuturor legăturilor.','<!doctype html><html><head><base href="https://example.com/shop/"><title>Shop</title></head><body><a href="cakes">Cakes</a></body></html>',[attr('base','href','https://example.com/shop/'),attr('a','href','cakes')],q('Ce schimbă base href?','Baza adreselor relative','Textul tuturor titlurilor','Portul PostgreSQL'),'Adaugă în head un base către `https://example.com/shop/` și o legătură relativă `cakes`, cu textul `Cakes`.')
H(c,'html-download-link','Legătură de descărcare','download sugerează salvarea resursei. Restricțiile de origine și răspunsul serverului pot influența comportamentul.','<a href="menu.pdf" download="bakery-menu.pdf">Download menu</a>',[attr('a','href','menu.pdf'),attr('a','download','bakery-menu.pdf'),exact('a','Download menu')],q('Ce atribut sugerează descărcarea?','download','required','colspan'),'Adaugă un link către `menu.pdf`, cu numele de descărcare `bakery-menu.pdf` și textul `Download menu`.')
H(c,'html-safe-tab','Deschide o pagină într-o filă nouă','target=_blank cere o filă sau fereastră nouă; rel=noopener păstrează explicit separarea față de opener.','<a href="https://example.com" target="_blank" rel="noopener">More information</a>',[attr('a','target','_blank'),attr('a','rel','noopener')],q('Ce valoare target deschide de regulă o filă nouă?','_blank','_self','download'),'Creează o legătură către `https://example.com`, cu target `_blank`, rel `noopener` și textul `More information`.')
H(c,'html-break-word','Punct de rupere opțional','br introduce o ruptură de linie; wbr indică doar un loc unde browserul poate rupe un cuvânt lung.','<p>sweet<wbr>corner<br>bakery</p>',[count('p wbr'),count('p br'),exact('p','sweetcornerbakery')],q('Ce element indică un loc opțional de rupere?','wbr','br întotdeauna','hr'),'Într-un paragraf, separă `sweet` și `corner` cu wbr, apoi adaugă br înainte de `bakery`.')
for obsolete,modern,meaning in [('font','span','Stilul textului se controlează prin CSS, nu prin elementul font.'),('center','div','Centrarea se face prin CSS; center este un element vechi.'),('acronym','abbr','Pentru abrevieri se folosește abbr în HTML modern.'),('strike','s','Pentru informații depășite folosește s; pentru revizii folosește del.'),('tt','code','Pentru cod folosește code; un font monospațiat se poate aplica și prin CSS.'),('frameset','iframe','Frameset și frame apar în documente vechi. Pentru un document încorporat studiază iframe și alternativele potrivite scopului.')]:
 concept(c,'legacy-'+obsolete,'Recunoaște '+obsolete,meaning,f'Legacy element: <{obsolete}>',q('Ce element modern este potrivit aici?',modern,obsolete,'script'),f'Înlocuiește numele elementului vechi `{obsolete}` cu numele alternativei moderne explicate mai sus. Scrie numai numele tagului.',modern)

c=chapter('html-controls-complete','HTML · formulare, tabele și media','Fiecare control și atribut important este exersat cu date incluse.','Introducere & HTML.pptx, 68–94; formularele și media exemplului de site','image')
H(c,'form-textarea','Mesaj pe mai multe rânduri','textarea primește textul inițial între taguri, nu într-un atribut value.','<label for="message">Message</label><textarea id="message" name="message" rows="4">Hello</textarea>',[attr('textarea','name','message'),attr('textarea','rows','4'),exact('textarea','Hello'),attr('label','for','message')],q('Unde scrii textul inițial al textarea?','Între taguri','În atributul src','În rel'),'Adaugă un textarea numit `message`, cu id `message`, 4 rânduri și textul inițial `Hello`. Leagă eticheta `Message` de el.')
H(c,'form-fieldset','Grupează controale înrudite','fieldset grupează controale, iar legend oferă numele grupului.','<fieldset><legend>Delivery</legend><label><input type="radio" name="delivery" value="pickup" checked> Pickup</label><label><input type="radio" name="delivery" value="courier"> Courier</label></fieldset>',[exact('legend','Delivery'),count('input[name="delivery"]',2),attr('input[value="pickup"]','type','radio')],q('Ce element denumește un fieldset?','legend','caption','figcaption'),'Grupează două radio cu name `delivery`, valorile `pickup` și `courier`; primul este bifat. Denumește grupul `Delivery`.')
H(c,'form-email','Email obligatoriu','type=email oferă o validare de format în browser, iar required cere o valoare. Serverul trebuie să valideze separat datele primite.','<label for="email">Email</label><input id="email" name="email" type="email" required>',[attr('input','type','email'),count('input[required]'),attr('label','for','email')],q('Ce atribut cere o valoare?','required','placeholder','title'),'Adaugă un câmp email obligatoriu, cu id și name `email`, și eticheta `Email`.')
H(c,'form-number','Număr cu limite și pas','min, max și step descriu valorile permise. value din DOM este text și trebuie convertit înainte de calcule.','<input id="quantity" type="number" min="1" max="10" step="1" value="2">',[attr('#quantity','min','1'),attr('#quantity','max','10'),attr('#quantity','step','1'),attr('#quantity','value','2')],q('Ce tip are în mod obișnuit input.value?','string','number automat','boolean'),'Creează un input number `quantity`, de la 1 la 10, cu pas 1 și valoare inițială 2.')
H(c,'form-submit-reset','Butoane cu rol explicit','submit trimite formularul, reset revine la valorile inițiale, iar button nu trimite formularul automat.','<form><button type="submit">Send</button><button type="reset">Reset</button><button type="button">Preview</button></form>',[count('button[type="submit"]'),count('button[type="reset"]'),count('button[type="button"]')],q('Ce tip folosești pentru un buton care nu trimite formularul?','button','submit','reset'),'Într-un form, adaugă butoanele `Send` de tip submit, `Reset` de tip reset și `Preview` de tip button.')
H(c,'form-disabled-readonly','disabled și readonly','Un control disabled nu este trimis în formular. Un control readonly poate păstra o valoare trimisă, dar nu este editabil prin interfața obișnuită.','<input name="code" value="ORDER-1" readonly><input name="temporary" value="x" disabled>',[count('input[name="code"][readonly]'),count('input[name="temporary"][disabled]')],q('Ce control nu se trimite ca parte normală a formularului?','Cel disabled','Orice control readonly','Orice control cu name'),'Creează un câmp `code` cu valoarea `ORDER-1`, readonly, și unul `temporary` cu valoarea `x`, disabled.')
H(c,'table-groups','Antet, corp și subsol de tabel','thead, tbody și tfoot delimitează grupuri de rânduri; caption denumește tabelul.','<table><caption>Order</caption><thead><tr><th scope="col">Item</th><th scope="col">Price</th></tr></thead><tbody><tr><td>Cake</td><td>12</td></tr></tbody><tfoot><tr><th scope="row">Total</th><td>12</td></tr></tfoot></table>',[exact('caption','Order'),count('thead th',2),exact('tbody td','Cake'),exact('tfoot th','Total')],q('Ce element conține subsolul tabelului?','tfoot','footer obligatoriu','figcaption'),'Construiește tabelul `Order`, cu antetele `Item` și `Price`, un rând `Cake`, `12`, și un subsol cu `Total`, `12`.')
H(c,'table-colgroup','Grupează coloanele','colgroup și col descriu coloane pentru anumite stiluri comune. Nu înlocuiesc celulele tr și td.','<table><colgroup><col span="2" class="product-columns"></colgroup><tbody><tr><td>Cake</td><td>12</td></tr></tbody></table>',[attr('col','span','2'),attr('col','class','product-columns'),count('tr td',2)],q('Ce element descrie o coloană sau un grup de coloane?','col','td în loc de col','caption'),'Adaugă un colgroup cu un col de span 2 și clasa `product-columns`, apoi un rând cu celulele `Cake` și `12`.')
H(c,'media-source-types','Surse video alternative','Browserul poate alege prima sursă compatibilă. Tipul MIME descrie formatul resursei, nu numele elementului HTML.','<video controls><source src="bakery.mp4" type="video/mp4"><source src="bakery.ogv" type="video/ogg"></video>',[attr('source:first-child','type','video/mp4'),attr('source:nth-child(2)','type','video/ogg'),count('video[controls]')],q('Ce atribut descrie formatul unei surse?','type','title','name'),'Adaugă un video cu controls și două surse, `bakery.mp4` de tip video/mp4 și `bakery.ogv` de tip video/ogg.')
H(c,'media-loading','Încărcare amânată și dimensiuni','loading=lazy poate amâna o imagine. width și height rezervă spațiul și pot reduce salturile de layout.','<img src="cake.webp" alt="Chocolate cake" width="600" height="400" loading="lazy">',[attr('img','width','600'),attr('img','height','400'),attr('img','loading','lazy'),attr('img','alt','Chocolate cake')],q('Ce ajută la rezervarea spațiului imaginii?','width și height','Doar title','Numele variabilei JavaScript'),'Adaugă imaginea `cake.webp`, cu alt `Chocolate cake`, dimensiuni 600×400 și loading lazy.')
concept(c,'vtt-cue-position','Poziționarea subtitrărilor','O intrare WebVTT poate specifica poziționarea după intervalul de timp. line:0 solicită plasarea pe linia indicată, în funcție de regulile de layout ale playerului.','WEBVTT\n\n00:00:01.000 --> 00:00:03.000 line:0\nFresh cakes',q('Unde scrii setarea line:0?','După intervalul de timp','În numele fișierului','Într-un atribut CSS al body'),'Scrie setarea care poziționează subtitrarea pe linia zero.','line:0')

c=chapter('css-selectors-complete','CSS · selectori și stări în detaliu','Potriviri exacte, frați, poziții și controale interactive.','MathML si CSS.pptx, 33–48','palette')
selectors=[
 ('attr-prefix','[href^="https"]','<a href="https://example.com">Secure</a><a href="/home">Home</a>','Potrivește începutul valorii atributului.'),
 ('attr-suffix','[href$=".pdf"]','<a href="menu.pdf">Menu</a><a href="home.html">Home</a>','Potrivește sfârșitul valorii; nu verifică singur tipul MIME.'),
 ('attr-substring','[href*="cake"]','<a href="/products/cakes">Cakes</a><a href="/tea">Tea</a>','Potrivește un subșir oriunde în valoare.'),
 ('attr-word','[class~="featured"]','<p class="card featured">Cake</p><p class="featured-card">Tea</p>','Potrivește un cuvânt separat prin spații, nu orice subșir.'),
 ('attr-language','[lang|="en"]','<p lang="en-GB">Cake</p><p lang="ro">Prăjitură</p>','Potrivește valoarea exactă sau urmată de cratimă.'),
 ('first-child','li:first-child','<ul><li>First</li><li>Second</li><li>Third</li></ul>','Alege primul copil, dacă are și tipul li.'),
 ('last-child','li:last-child','<ul><li>First</li><li>Second</li></ul>','Alege ultimul copil, dacă are și tipul li.'),
 ('nth-odd','li:nth-child(odd)','<ul><li>One</li><li>Two</li><li>Three</li></ul>','odd corespunde pozițiilor 1,3,5; elementele sunt numărate de la 1.'),
 ('nth-even','li:nth-child(even)','<ul><li>One</li><li>Two</li><li>Three</li></ul>','even corespunde pozițiilor 2,4,6.'),
 ('nth-formula','li:nth-child(3n+1)','<ul><li>One</li><li>Two</li><li>Three</li><li>Four</li></ul>','3n+1 selectează pozițiile 1,4,7 și așa mai departe.'),
 ('nth-type','p:nth-of-type(2)','<div><p>First</p><h2>Title</h2><p>Second paragraph</p></div>','Numără doar frații cu același tip de element.'),
 ('only-child','p:only-child','<section><p>Alone</p></section><section><p>A</p><p>B</p></section>','Alege un p care nu are frați elemente.'),
 ('not','p:not(.muted)','<p>Active</p><p class="muted">Muted</p>','Exclude elementele care corespund selectorului din paranteze.'),
 ('empty','.message:empty','<p class="message"></p><p class="message">Text</p>','Alege elemente fără copii elemente sau noduri text; spațiile pot conta.'),
 ('general-sibling','h2 ~ p','<section><h2>Offers</h2><p>A</p><div>Gap</div><p>B</p></section>','Alege frații ulteriori cu același părinte, chiar dacă nu sunt imediat alăturați.'),
 ('checked','input:checked','<input type="checkbox" checked><input type="checkbox">','Alege checkbox-uri sau radio selectate.'),
 ('disabled','input:disabled','<input disabled><input>','Alege controale dezactivate.'),
 ('required','input:required','<input required><input>','Alege controale care solicită o valoare.')]
for key,selector,fixture,idea in selectors:
 C(c,'selector-'+key,selector,idea,selector+' { color: navy; }',fixture,[prop(selector,'color','rgb(0, 0, 128)')],q('Ce sintaxă selectează elementele descrise?',selector,'@'+key,'::'+key+'-all'),f'Fă textul elementelor selectate prin `{selector}` de culoare `navy`. '+idea)

c=chapter('css-effects-complete','CSS · efecte, fonturi și accesibilitate','Fundaluri, animații, focus, subtitrări și pregătirea pentru print.','MathML si CSS.pptx, 49–68, 88–101; CSS-ul site-ului','palette')
C(c,'css-radial','Gradient radial','Un gradient radial pornește dintr-un centru și se extinde spre exterior.','.card { background-image: radial-gradient(circle, navy, teal); }','<div class="card">Cake</div>',[dict(kind='cssIncludes',value='radial-gradient(circle, navy, teal)',label='Gradient radial')],q('Ce funcție produce gradientul radial?','radial-gradient','linear-gradient obligatoriu','background-position'),'Aplică pe `.card` un gradient radial circular de la navy la teal.')
C(c,'css-calc','Calcule între unități','calc permite calcule între valori compatibile. Operațiile + și - cer spații în expresia CSS.','.card { width: calc(100% - 40px); }','<div class="card">Cake</div>',[dict(kind='cssIncludes',value='calc(100% - 40px)',label='Lățime calculată')],q('Ce este calc(100% - 40px)?','Lățimea disponibilă minus 40px','Un număr de coloane','O interogare SQL'),'Setează lățimea `.card` la lățimea containerului minus 40px folosind calc.')
C(c,'css-variable-fallback','Valoare de rezervă pentru var','Al doilea argument al var este folosit dacă proprietatea personalizată lipsește sau nu poate fi substituită conform regulilor variabilelor.','.card { color: var(--accent, navy); }','<p class="card">Cake</p>',[prop('.card','color','rgb(0, 0, 128)')],q('Ce culoare este folosită când --accent lipsește?','navy','transparent obligatoriu','Niciuna'),'Folosește `var(--accent, navy)` pentru culoarea `.card`, fără să definești --accent.')
C(c,'css-global-values','inherit pentru o proprietate explicită','inherit cere valoarea calculată a părintelui chiar și pentru proprietăți care nu se moștenesc implicit.','.parent { border: 2px solid navy; } .child { border: inherit; }','<div class="parent"><p class="child">Cake</p></div>',[prop('.child','border-top-width','2px'),prop('.child','border-top-color','rgb(0, 0, 128)')],q('De unde ia inherit valoarea?','De la părinte','Din favicon','De la ultimul vecin'),'Pune pe `.parent` un border de 2px solid navy și moștenește explicit border-ul pe `.child`.')
C(c,'css-animation-direction','Animație înainte și înapoi','alternate inversează direcția la fiecare ciclu. animation-direction nu este aceeași proprietate cu flex-direction.','@keyframes fade { from { opacity:0; } to { opacity:1; } } .card { animation:fade 2s linear infinite alternate; }','<div class="card">Cake</div>',[prop('.card','animation-direction','alternate'),prop('.card','animation-iteration-count','infinite')],q('Ce valoare alternează sensul animației?','alternate','reverse-only-all','column'),'Definește fade de la opacity 0 la 1 și aplic-o pe `.card`: 2 secunde, linear, infinite, alternate.')
C(c,'css-animation-pause','Oprește temporar animația','animation-play-state:paused păstrează animația în starea curentă. Nu o elimină din stil.','@keyframes fade { from { opacity:0; } to { opacity:1; } } .card { animation:fade 2s infinite; animation-play-state:paused; }','<div class="card">Cake</div>',[prop('.card','animation-play-state','paused')],q('Ce proprietate controlează pauza animației?','animation-play-state','display-state','transition-pause'),'Aplică animația fade pe `.card` și setează animation-play-state la paused.')
C(c,'css-font-face','Declară un font local','@font-face leagă o familie de font de o resursă. font-display:swap permite afișarea unui font alternativ în timp ce resursa se încarcă.','@font-face { font-family: "Bakery"; src: url("bakery.woff2") format("woff2"); font-display: swap; } .title { font-family:"Bakery",sans-serif; }','<h1 class="title">Bakery</h1>',[dict(kind='cssIncludes',value='@font-face',label='Declarație font'),dict(kind='cssIncludes',value='font-display:swap',label='Afișare cu fallback')],q('Ce declară o familie dintr-un fișier de font?','@font-face','font-size','@keyframes'),'Declară fontul Bakery din bakery.woff2, cu font-display swap, și aplică familia pe `.title` cu rezervă sans-serif.')
C(c,'css-cue','Stilizează subtitrările','Pseudo-elementul ::cue vizează indicii de subtitrare ai elementelor media. Nu selectează un paragraf HTML obișnuit.','video::cue { color: white; background: navy; }','<video></video>',[dict(kind='cssIncludes',value='video::cue',label='Stil pentru subtitrări'),dict(kind='cssIncludes',value='background:navy',label='Fundal navy')],q('Ce stilizează ::cue?','Subtitrările media','Toate linkurile','Celulele unui tabel'),'Scrie o regulă video::cue cu text white și fundal navy.')
C(c,'css-focus-link','Linkuri accesibile cu tastatura',':focus-visible permite un indiciu vizibil pentru navigarea cu tastatura. Nu elimina conturul fără o alternativă.','a:focus-visible { outline: 3px solid orange; }','<a href="#home">Home</a>',[dict(kind='cssIncludes',value='a:focus-visible',label='Focus vizibil'),dict(kind='cssIncludes',value='outline:3px solid orange',label='Contur de focus')],q('Ce stare ajută utilizatorul care navighează cu Tab?',':focus-visible','::after obligatoriu',':visited singur'),'La focus vizibil, dă linkurilor un outline de 3px solid orange.')
C(c,'css-print-clean','Aspect pentru imprimare','Un media query pentru print poate elimina navigarea și controalele care nu ajută pe hârtie.','@media print { .site-menu, .actions { display:none; } }','<nav class="site-menu">Menu</nav><div class="actions">Filter</div>',[dict(kind='cssIncludes',value='@media print',label='Stil de printare'),dict(kind='cssIncludes',value='display:none',label='Controale ascunse la print')],q('Ce tip media vizează imprimarea?','print','screen','paper-size'),'Ascunde `.site-menu` și `.actions` numai în media print.')
